package tests

// The resolve-capability signing key must never be generated by the chart.
//
// `lookup` needs a live cluster and returns empty under `helm template`, which
// is Argo CD's render mode — so a generated key is fresh on EVERY reconcile.
// Argo sees a Secret diff every time, syncs it, and neither process re-reads
// the file, so the rotation is invisible until the first asymmetric restart,
// after which each side rejects the other's capabilities and every build's
// input fetch 403s. Argo CD has no chart-side "create once, never update" for
// a rendered resource, so the only sound answer is to keep the key OUT of the
// render: the operator creates the Secret once, out of band, and the chart
// only ever references it by name.

import (
	"strings"
	"testing"
)

// Nothing in the chart may mint key material. A single `randBytes`/`genCA`-
// style call in a Secret is enough to reintroduce the rotation hazard.
func TestChartNeverGeneratesTheResolveCapabilityKey(t *testing.T) {
	for _, sets := range [][]string{
		nil,
		{"artifactDaemon.resolveCapability.existingSecret=my-key"},
	} {
		out := render(t, sets...)
		if strings.Contains(out, "resolve.key:") {
			t.Errorf("render %v emits Secret data for resolve.key; the key must be created out of band, not rendered", sets)
		}
	}
}

// The two sides must agree. The daemon fails CLOSED once it is given a key, so
// a render that arms the daemon without arming the web (or the reverse) fails
// every resolve on the node with a 403 and no diagnostic. Gating both on ONE
// value is what makes that state unreachable.
func TestResolveCapabilityFlagsAreAllOrNothing(t *testing.T) {
	const (
		daemonFlag = "--resolve-capability-key="
		webFlag    = "--kubernetes-artifact-daemon-resolve-capability-key="
	)

	t.Run("no secret named: neither side enforces", func(t *testing.T) {
		out := render(t)
		if strings.Contains(out, daemonFlag) {
			t.Error("the daemon requires capabilities with no Secret configured; it will 403 every resolve")
		}
		if strings.Contains(out, webFlag) {
			t.Error("the web signs capabilities with no Secret configured")
		}
		if strings.Contains(out, "/etc/concourse/resolve-capability") {
			t.Error("a capability volume is mounted with no Secret configured; the pod cannot start")
		}
	})

	t.Run("secret named: both sides enforce", func(t *testing.T) {
		out := render(t, "artifactDaemon.resolveCapability.existingSecret=jb-resolve-key")
		if !strings.Contains(out, daemonFlag) {
			t.Error("the daemon does not verify capabilities although a Secret is configured")
		}
		if !strings.Contains(out, webFlag) {
			t.Error("the web does not sign capabilities although a Secret is configured")
		}
		if strings.Count(out, "secretName: jb-resolve-key") != 2 {
			t.Errorf("expected both web and daemon to mount the named Secret; got:\n%s", capabilityLines(out))
		}
	})

	t.Run("daemon disabled: no capability wiring anywhere", func(t *testing.T) {
		out := render(t,
			"artifactDaemon.enabled=false",
			"artifactDaemon.resolveCapability.existingSecret=jb-resolve-key",
		)
		if strings.Contains(out, webFlag) {
			t.Error("the web signs capabilities for a daemon that is not deployed")
		}
	})
}

// The TTL flag is worthless without the key flag: the ATC refuses to start when
// the TTL is at or below its floor, and never signs at all without a key.
func TestResolveCapabilityTTLTravelsWithTheKey(t *testing.T) {
	out := render(t)
	if strings.Contains(out, "resolve-capability-ttl") {
		t.Error("a capability TTL is passed with no Secret configured")
	}

	out = render(t, "artifactDaemon.resolveCapability.existingSecret=jb-resolve-key")
	if !strings.Contains(out, "--kubernetes-artifact-daemon-resolve-capability-ttl=2h") {
		t.Errorf("expected the default 2h TTL alongside the key; got:\n%s", capabilityLines(out))
	}
}

func capabilityLines(out string) string {
	var b strings.Builder
	for _, line := range strings.Split(out, "\n") {
		if strings.Contains(line, "resolve-capability") || strings.Contains(line, "secretName:") {
			b.WriteString(line)
			b.WriteString("\n")
		}
	}
	return b.String()
}
